<?php
require_once __DIR__ . '/../includes/auth.php'; require_guest();
if (empty($_SESSION['reset_verified']) || empty($_SESSION['otp_user_id'])) { redirect(APP_URL . '/?page=forgot-password'); }
$errors = [];
if (is_post()) { $password = $_POST['password'] ?? ''; $confirmation = $_POST['password_confirmation'] ?? ''; if (!verify_csrf()) $errors[] = 'Sesi formulir tidak valid.'; if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) || !preg_match('/[0-9]/', $password)) $errors[] = 'Password minimal 8 karakter, dengan huruf besar dan angka.'; if ($password !== $confirmation) $errors[] = 'Konfirmasi password tidak sama.'; if (!$errors) { db()->prepare('UPDATE users SET password_hash = ? WHERE id = ?')->execute([password_hash($password, PASSWORD_DEFAULT), $_SESSION['otp_user_id']]); unset($_SESSION['otp_user_id'], $_SESSION['otp_channel'], $_SESSION['dev_otp'], $_SESSION['reset_verified']); flash('success', 'Password berhasil diubah. Silakan login dengan password baru.'); redirect(APP_URL . '/?page=login'); } }
$pageTitle = 'Reset Password'; require __DIR__ . '/../includes/header.php';
?><section class="auth-section"><div class="auth-shell"><div class="auth-intro"><span class="eyebrow">Akun terlindungi</span><h1>Buat password<br><em>yang baru.</em></h1><p>Pilih password yang kuat agar akun dan aktivitasmu tetap aman.</p></div><div class="auth-panel glass-card"><div class="auth-heading"><span class="auth-icon"><i class="bi bi-lock"></i></span><div><h2>Reset password</h2><p>Hampir selesai.</p></div></div><?php if ($errors): ?><div class="alert alert-danger small"><?= implode('<br>', array_map('e', $errors)) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="form-label">Password baru</label><input class="form-control mb-3" type="password" name="password" placeholder="Min. 8 karakter"><label class="form-label">Konfirmasi password</label><input class="form-control mb-4" type="password" name="password_confirmation" placeholder="Ulangi password"><button class="btn btn-primary w-100" type="submit">Simpan password <i class="bi bi-check2 ms-2"></i></button></form></div></div></section><?php require __DIR__ . '/../includes/footer.php'; ?>